import bisect

class Solution:
    def longestObstacleCourseAtEachPosition(self, obstacles: list[int]) -> list[int]:
        tails = []
        ans = []
        for x in obstacles:
            idx = bisect.bisect_right(tails, x)
            if idx == len(tails):
                tails.append(x)
            else:
                tails[idx] = x
            ans.append(idx + 1)
        return ans

class Solution {
public:
    vector<int> longestObstacleCourseAtEachPosition(vector<int>& obstacles) {
        vector<int> tails;
        vector<int> ans;
        for (int x : obstacles) {
            auto it = upper_bound(tails.begin(), tails.end(), x);
            int idx = it - tails.begin();
            if (it == tails.end()) tails.push_back(x);
            else *it = x;
            ans.push_back(idx + 1);
        }
        return ans;
    }
};

class Solution {
    public int[] longestObstacleCourseAtEachPosition(int[] obstacles) {
        int n = obstacles.length;
        int[] tails = new int[n];
        int[] ans = new int[n];
        int len = 0;
        for (int i = 0; i < n; i++) {
            int x = obstacles[i];
            int low = 0, high = len;
            while (low < high) {
                int mid = (low + high) / 2;
                if (tails[mid] <= x) low = mid + 1;
                else high = mid;
            }
            tails[low] = x;
            if (low == len) len++;
            ans[i] = low + 1;
        }
        return ans;
    }
}

var longestObstacleCourseAtEachPosition = function(obstacles) {
  const tails = [];
  const ans = [];
  for (const x of obstacles) {
    let low = 0, high = tails.length;
    while (low < high) {
      const mid = (low + high) >> 1;
      if (tails[mid] <= x) low = mid + 1;
      else high = mid;
    }
    if (low === tails.length) tails.push(x);
    else tails[low] = x;
    ans.push(low + 1);
  }
  return ans;
};
